package com.revivex.engine; import com.revivex.domain.*; import org.springframework.stereotype.Component; @Component public class PolicyEngine { public PolicyDecision check(PaymentEvent p,MerchantPolicy policy,String action){if(p.isHighRisk())return new PolicyDecision(false,"High-risk case: recovery action blocked.","BLOCK_HIGH_RISK",0);if(p.getPreviousAttempts()>=policy.getMaxRetries()&&!action.equals("B2B_CHASER")&&!action.equals("STOP"))return new PolicyDecision(false,"Retry budget exhausted.","MAX_PAYMENT_RETRIES",Math.max(0,policy.getMaxRetries()-p.getPreviousAttempts()));if(p.getPreviousContacts()>=policy.getMaxContacts()&&!action.equals("STOP")&&!action.equals("SMART_RETRY"))return new PolicyDecision(false,"Customer contact budget exhausted.","MAX_CUSTOMER_CONTACTS",Math.max(0,policy.getMaxContacts()-p.getPreviousContacts()));if(action.equals("PAYMENT_NUDGE")&&!policy.isAllowCustomerNudge())return new PolicyDecision(false,"Merchant policy disables customer nudges.","ALLOW_CUSTOMER_NUDGE",0);if(action.equals("B2B_CHASER")&&!policy.isAllowB2BChaser())return new PolicyDecision(false,"Merchant policy disables B2B chasing.","ALLOW_B2B_CHASER",0);return new PolicyDecision(true,"Policy permits this bounded intervention.","POLICY_ALLOW",Math.max(0,policy.getMaxRetries()-p.getPreviousAttempts()));} public String stopRule(PaymentEvent p,MerchantPolicy m,String action){if(p.isHighRisk())return "STOP_HIGH_RISK";if(p.getPreviousAttempts()>=m.getMaxRetries())return "STOP_RETRY_BUDGET_EXHAUSTED";if(p.getPreviousContacts()>=m.getMaxContacts()&&!action.equals("SMART_RETRY"))return "STOP_CONTACT_BUDGET_EXHAUSTED";if(action.equals("STOP"))return "STOP_POLICY_BLOCKED";return "STOP_AFTER_SUCCESS_OR_POLICY_BOUNDARY";} public record PolicyDecision(boolean allowed,String reason,String rule,int remainingBudget){} }
